using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace NightLens {
static class ObjectTests {
 public static int FetchImages(string[] args){ObjectImages.CacheFolder=Path.GetFullPath(args[1]);var settings=args.Length>3?Settings.Load():new Settings{WindowsLocation=false};settings.RestoreSaved();var targets=new List<Target>();foreach(int active in Enumerable.Range(0,args.Length>3?settings.Rigs.Count:1)){settings.Active=active;var night=new Night(settings,new Forecast(),new DateTime(2026,10,25,18,0,0,DateTimeKind.Utc),new DateTime(2026,10,25));targets.AddRange(night.Picks.Select(p=>p.Target));}string notice;var pelican=CatalogLibrary.Load(settings,out notice).FirstOrDefault(t=>t.Aliases.Contains("IC5070"));if(pelican!=null)targets.Add(pelican);var log=new List<string>();foreach(var target in targets.GroupBy(t=>ObjectImages.PathFor(t)).Select(g=>g.First())){string file=ObjectImages.Get(target,true,true).GetAwaiter().GetResult();log.Add(target.Name+" | "+(file??"IMAGE FAILED: "+ObjectImages.ErrorFor(target))+" | "+ObjectImages.Source(target));}File.WriteAllLines(args[2],log);return log.Any(line=>line.Contains("IMAGE FAILED"))?1:0;}


 static IEnumerable<Control> Walk(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in Walk(c))yield return child;}}
 public static void Run(Forecast f,DateTime now,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};ObjectImages.CacheFolder=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"object-image-cache");var settings=new Settings{WindowsLocation=false};var night=new Night(settings,f,now);check(night.Picks.Count==3,"Exactly three objects selected when enough targets qualify");var track=ObjectInfo.Track(night.Picks[0],night);check(track.Count>=3&&track.First().Utc==night.Dark.First()&&track.Last().Utc==night.Dark.Last()&&track.Any(t=>t.Utc==night.Picks[0].Best),"Altitude trajectory spans darkness and includes the best time");check(track.Where(p=>p.Utc>=night.Picks[0].Start&&p.Utc<=night.Picks[0].End).All(p=>p.Alt<=night.Picks[0].Alt+.03),"Highlighted best altitude agrees with trajectory samples");check(track.All(p=>Math.Abs(p.Alt-night.Altitude(night.Picks[0].Target,p.Utc))<.000001&&p.Az>=0&&p.Az<=360),"Trajectory heights and directions use the observer's astronomical coordinates");check(ObjectInfo.RA(23.999999)=="00h 00m 00s"&&ObjectInfo.Dec(-1.5).StartsWith("−01° 30′"),"Coordinate display carries seconds and preserves declination sign");
 string notice;var targets=CatalogLibrary.Load(settings,out notice);var galaxy=targets.First(t=>t.Vmag.HasValue&&t.Bmag.HasValue&&t.SurfaceBrightness.HasValue);check(galaxy.SurfaceBrightness>0&&galaxy.MagnitudeBand!=null,"Photometric bands and surface brightness survive catalog merging");var justB=CatalogLibrary.Parse("Name;Type;RA;Dec;MajAx;MinAx;B-Mag;V-Mag;SurfBr\nNGC9999;G;01:00:00;+20:00:00;2;1;12.3;;23.4", "Fixture.csv").Targets.Single();check(justB.Bmag==12.3&&justB.Vmag==null&&justB.MagnitudeBand=="B"&&justB.Magnitude==12.3,"B-only magnitude never gets mislabeled as V");var missing=new Pick{Target=new Target("Unknown","Galaxy",1,20,0,0)};check(ObjectInfo.Photometry(missing).Contains("not cataloged")&&ObjectInfo.Surface(missing.Target).Contains("not cataloged"),"Missing photometric values are explicit rather than invented");check(ObjectInfo.Coordinates(night.Picks[0],night).Contains(night.Picks[0].Target.Body.HasValue?"of date":"J2000"),"Coordinates identify the correct epoch for moving or fixed targets");check(ObjectInfo.Description(galaxy).Length>60&&ObjectInfo.Full(new Pick{Target=galaxy,Best=night.Picks[0].Best},night).Contains("J "),"Object information includes classification, constellation, infrared bands and sources");check(ObjectImages.Source(galaxy).Contains("J2000"),"Survey images identify catalog coordinate epoch");check(ObjectImages.Source(galaxy).Contains("Pan-STARRS")&&ObjectImages.Source(galaxy).Contains("DSS2"),"Independent optical color surveys are documented");check(ObjectImages.Field(new Target("Large","Nebula",1,1,200,100))==120,"Large objects get a clearly labeled central field within survey limits");
 foreach(string body in new[]{"Moon","Jupiter","Saturn","Mars","Venus"})using(var photo=Image.FromFile(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Assets","Objects",body+".jpg"))){check(Math.Max(photo.Width,photo.Height)>=1000,body+" reference image has at least 1000 pixels on its longest side");}var originalCache=ObjectImages.CacheFolder;try{ObjectImages.CacheFolder=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"photo-fixture");Directory.CreateDirectory(ObjectImages.CacheFolder);File.Copy(Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"dss-test.gif"),ObjectImages.PathFor(galaxy),true);check(ObjectImages.Get(galaxy,false).Result!=null,"Previously fetched object photos remain available offline");}finally{ObjectImages.CacheFolder=originalCache;}
 using(var main=new MainForm(true)){main.LoadTest(f,now);main.Show();Application.DoEvents();main.Size=main.MinimumSize;Application.DoEvents();CheckFacts(main,check);check(Walk(main).Count(c=>Equals(c.Tag,"object-card"))==1,"Dashboard shows one best object at a time");check(Walk(main).OfType<Label>().Any(c=>c.Text.Contains("1 / 3")),"Object navigation shows one of three recommendations");Walk(main).OfType<Button>().Single(c=>c.Text=="Next ›").PerformClick();Application.DoEvents();CheckFacts(main,check);check(Walk(main).Count(c=>Equals(c.Tag,"object-card"))==1&&Walk(main).OfType<Label>().Any(c=>c.Text.Contains("2 / 3")),"Next changes the displayed object without adding cards");Walk(main).OfType<Button>().Single(c=>c.Text=="Next ›").PerformClick();Application.DoEvents();CheckFacts(main,check);check(!Walk(main).OfType<Button>().Single(c=>c.Text=="Next ›").Enabled,"Next stops at the third object");var chart=Walk(main).OfType<AltitudeChart>().Single();check(!chart.BestReadoutBounds.IntersectsWith(chart.PlotBounds)&&chart.BestReadoutBounds.Bottom<chart.PlotBounds.Top,"Altitude/time readout stays outside the plotted curve");check(chart.Samples.All(sample=>{var point=chart.Project(sample);return point.X>=chart.PlotBounds.Left-.01&&point.X<=chart.PlotBounds.Right+.01&&point.Y>=chart.PlotBounds.Top&&point.Y<=chart.PlotBounds.Bottom;}),"Entire altitude trajectory, including below-horizon samples, fits inside the graph");var map=Walk(main).OfType<SkyMap>().Single();PointF centered,east,north;check(StarCatalog.Data.Stars.Count==5044&&StarCatalog.Data.Lines.Count==150&&StarCatalog.Error=="","Offline star catalog loads 5044 real stars and 150 constellation line chains");check(map.VisibleStars>0&&map.VisibleSegments>0,"Star map draws real stars and constellation lines around the selected target");check(map.Project(map.CenterRa,map.CenterDec,out centered)&&Math.Abs(centered.X-map.MapBounds.Left-map.MapBounds.Width/2.0)<.01&&Math.Abs(centered.Y-map.MapBounds.Top-map.MapBounds.Height/2.0)<.01,"Selected object is centered accurately on the sky map");map.Project(map.CenterRa+1,map.CenterDec,out east);map.Project(map.CenterRa,map.CenterDec+1,out north);check(east.X<centered.X&&north.Y<centered.Y,"Star map orientation is north up and east left");check(PreviewDoubleClick(map,"Sky map ·",Path.Combine(Path.GetDirectoryName(args[3]),"Enlarged sky map preview.png")),"Sky map opens an enlarged constellation view");check(!PreviewDoubleClick(chart,"Altitude trajectory ·",Path.Combine(Path.GetDirectoryName(args[3]),"Enlarged trajectory preview.png")),"Altitude trajectory double-click no longer opens a window");check(!PreviewDoubleClick(Walk(main).OfType<ObjectPhoto>().Single(),"Reference image ·",Path.Combine(Path.GetDirectoryName(args[3]),"Enlarged reference image preview.png")),"Reference image double-click no longer opens a window");check(chart.Samples.Count>=145&&chart.Samples.First().Utc==night.Start&&chart.Samples.Last().Utc==night.End,"Altitude curve spans noon to noon with ten-minute samples");check(chart.Samples.All(point=>Math.Abs(point.Alt-night.Altitude(night.Picks[2].Target,point.Utc))<.000001),"Altitude curve uses the selected object and observing location");check(Walk(main).Any(c=>c is SkyMap)&&Walk(main).OfType<Button>().Any(c=>c.Text=="Hourly forecast"),"Three-column view keeps the position readout and hourly forecast access");check(Walk(main).Any(c=>c is ObjectPhoto)&&Walk(main).Any(c=>Equals(c.Tag,"altitude-sample")),"Each object view includes a reference photo and altitude trajectory");bool hourlyShown=false;using(var close=new System.Windows.Forms.Timer{Interval=120}){close.Tick+=(a,b)=>{close.Stop();var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(form=>form.Text=="Tonight by hour");if(dialog!=null){hourlyShown=Walk(dialog).OfType<StatusText>().Any()&&Walk(dialog).OfType<StatusText>().All(control=>dialog.ClientRectangle.Contains(dialog.RectangleToClient(control.RectangleToScreen(control.ClientRectangle))));using(var photo=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(photo,new Rectangle(Point.Empty,photo.Size));photo.Save(Path.Combine(Path.GetDirectoryName(args[3]),"Hourly forecast preview.png"));}dialog.Close();}};close.Start();Walk(main).OfType<Button>().Single(button=>button.Text=="Hourly forecast").PerformClick();}check(hourlyShown,"Hourly forecast opens a readable separate window with all hourly cards inside it");check(!Walk(main).OfType<ScrollableControl>().Any(c=>c.AutoScroll),"Expanded object view keeps the dashboard free of scrollbars");using(var image=new Bitmap(main.Width,main.Height)){main.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(Path.GetDirectoryName(args[3]),"Object details preview.png"));}}
 }
 static bool PreviewDoubleClick(Control control,string prefix,string path){bool shown=false;using(var close=new System.Windows.Forms.Timer{Interval=150}){close.Tick+=(a,b)=>{close.Stop();var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(form=>form.Text.StartsWith(prefix));if(dialog!=null){using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}shown=true;dialog.Close();}};close.Start();typeof(Control).GetMethod("OnDoubleClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(control,new object[]{EventArgs.Empty});}return shown;}
 static void CheckFacts(MainForm form,Action<bool,string> check){var facts=Walk(form).OfType<Label>().Single(c=>Equals(c.Tag,"object-facts"));var needed=TextRenderer.MeasureText(facts.Text,facts.Font,new Size(facts.Width,1000),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix|TextFormatFlags.TextBoxControl);check(needed.Height+3<=facts.Height,"All object facts fit without clipping at minimum window size");var photo=Walk(form).OfType<ObjectPhoto>().Single();var a=photo.RectangleToScreen(photo.ClientRectangle);var b=facts.RectangleToScreen(facts.ClientRectangle);check(a.Right<=b.Left,"Reference photo does not overlap the object's facts");}
}
}

